<?php
namespace Tests\Feature;
use App\Models\Admin;use App\Models\RolePermission;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Route;use Tests\TestCase;
class RbacTest extends TestCase { use RefreshDatabase;
 public function test_admin_permissions_are_live_and_homepage_is_super_admin_only():void { $admin=Admin::create(['name'=>'Admin','email'=>'rbac-admin@example.test','password'=>'password123','role'=>'admin','is_active'=>true]); $token=$admin->createToken('test',['admin'])->plainTextToken; $this->withToken($token)->getJson('/api/admin/homepage/banners')->assertForbidden()->assertJsonPath('permission','storefront.edit'); $this->withToken($token)->getJson('/api/admin/dashboard')->assertOk(); RolePermission::where('role','admin')->update(['permissions'=>[]]); \Illuminate\Support\Facades\Cache::forget('rbac.admin'); $this->withToken($token)->getJson('/api/admin/dashboard')->assertForbidden(); \Illuminate\Support\Facades\Cache::forget('rbac.admin'); }
 public function test_every_console_group_route_has_permission_or_is_self_service():void { $self=['api/admin/login','api/admin/forgot-password','api/admin/reset-password','api/admin/check-reset-code','api/admin/me','api/admin/logout','api/sellers/login','api/sellers/onboard','api/sellers/forgot-password','api/sellers/reset-password','api/sellers/check-reset-code','api/sellers/me','api/sellers/logout','api/seller/staff/me']; foreach(Route::getRoutes() as $route){$uri=$route->uri();if(!preg_match('~^api/(admin|seller)/~',$uri)||in_array($uri,$self,true)||str_contains($uri,'/me/'))continue;$has=collect($route->gatherMiddleware())->contains(fn($m)=>str_contains($m,'PermissionMiddleware') || str_starts_with($m,'perm:'));$this->assertTrue($has,"{$uri} has no perm middleware");} }
 public function test_roles_save_drops_forbidden_permissions_and_writes_an_audit_record():void { $super=Admin::create(['name'=>'Super','email'=>'rbac-super@example.test','password'=>'password123','role'=>'super_admin','is_active'=>true]);$token=$super->createToken('test',['admin'])->plainTextToken;$roles=collect(['admin','seller','seller_staff','reseller'])->map(fn($id)=>['id'=>$id,'permissions'=>['admins.manage','products.delete','dashboard.view','support.reply']])->all();$this->withToken($token)->postJson('/api/admin/roles',['roles'=>$roles])->assertOk()->assertJsonPath('2.permissions.0','dashboard.view');$this->assertDatabaseHas('audit_logs',['action'=>'roles.updated']);$this->assertNotContains('admins.manage',\App\Models\RolePermission::where('role','seller')->value('permissions'));$this->assertNotContains('products.delete',\App\Models\RolePermission::where('role','seller_staff')->value('permissions')); }

}
